package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateStatus {
    public void validate(@RequestBody StatusRequest request, Out<StatusInput> body) throws InvalidSheetException {
        String status = request == null || request.status() == null ? "" : request.status().trim();
        try {
            body.set(new StatusInput(ClaimStatus.valueOf(status), request.user()));
        } catch (IllegalArgumentException e) {
            throw new InvalidSheetException("Not a claim status: " + status);
        }
    }
}
EOF
cat > $C/ApplyStatus.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the new status, refusing a change its current status does not allow. */
public class ApplyStatus {
    public void apply(@Val StatusInput input, @Val Claim claim) throws InvalidSheetException {
        if (!claim.getStatus().canBecome(input.status())) {
            throw new InvalidSheetException(
                    "A " + claim.getStatus() + " claim cannot become " + input.status());
        }
        claim.setStatus(input.status());
    }
}
EOF
